<?php namespace App\Http\Controllers; use App\Models\{Vehicle,Customer}; use Illuminate\Http\Request;
class VehicleController extends Controller {public function index(Request $r){$vehicles=Vehicle::with('customer')->when($r->q,fn($q,$v)=>$q->where('registration_number','like','%'.$v.'%'))->latest()->paginate(15);return view('vehicles.index',compact('vehicles'));} public function create(Request $r){$customers=Customer::orderBy('full_name')->get();return view('vehicles.create',compact('customers'));} public function store(Request $r){$v=Vehicle::create($r->validate(['customer_id'=>'required|exists:customers,id','registration_number'=>'required|unique:vehicles,registration_number','make'=>'nullable','model'=>'nullable','category'=>'required','mileage'=>'nullable|integer']));return redirect()->route('vehicles.show',$v)->with('success','Vehicle created.');} public function show(Vehicle $vehicle){$vehicle->load('customer','jobs');return view('vehicles.show',compact('vehicle'));} public function edit(Vehicle $vehicle){$customers=Customer::all();return view('vehicles.edit',compact('vehicle','customers'));} public function update(Request $r,Vehicle $vehicle){$vehicle->update($r->validate(['customer_id'=>'required','registration_number'=>'required|unique:vehicles,registration_number,'.$vehicle->id,'make'=>'nullable','model'=>'nullable','category'=>'required','mileage'=>'nullable|integer']));return back()->with('success','Vehicle updated.');} public function destroy(){abort(405);}}
